                let answer = taskQuestion.options.ids;
                novoJson.answers[questionId] = { question_id: question.question_id, question_type: taskQuestion.type, answer };
            } else {
                // Fallback para outros tipos
                let answer = Object.fromEntries(Object.keys(taskQuestion.options).map(optId => [optId, taskQuestion.options[optId].answer]));
                novoJson.answers[questionId] = { question_id: question.question_id, question_type: taskQuestion.type, answer };
            }
        }
        return novoJson;
    }

    const observer = new MutationObserver(() => {
        if (document.location.href !== oldHref) {
            oldHref = document.location.href;

            if (lesson_regex.test(oldHref)) {
                console.log("[CMSP] Tarefa detectada! Iniciando envio...");

                // 1. Verificar Auth Token
                try {
                    let stateData = sessionStorage.getItem("cmsp.ip.tv:iptvdashboard:state");
                    if (!stateData) {
                        throw new Error("Autenticação não encontrada no sessionStorage.");
                    }
                    let parsedState = JSON.parse(stateData);
                    let authToken = parsedState.auth.auth_token;
                    let roomName = parsedState.room.room.name;

                    console.log(`[CMSP] Token validado. Sala: ${roomName}`);
                } catch (e) {
                    console.error("[CMSP] ERRO DE AUTENTICAÇÃO:", e.message);
                    alert("Erro: Não foi possível encontrar sua sessão de login. Tente recarregar a página.");
                    return;
                }

                let id = oldHref.split("/")[6];

                // Função auxiliar de requisição
                const sendRequest = (method, url, data, callback) => {
                    const xhr = new XMLHttpRequest();
                    xhr.open(method, url);
                    xhr.setRequestHeader("X-Api-Key", authToken);
                    xhr.setRequestHeader("Content-Type", "application/json");
                    xhr.onload = () => callback(xhr);
                    xhr.onerror = () => { console.error("Falha na requisição XHR"); callback(xhr); };
                    xhr.send(data ? JSON.stringify(data) : null);
                };

                // Passo 1: Criar Draft
                let draft_body = {
                    status: "draft",
                    accessed_on: "room",
                    executed_on: roomName,
                    answers: {}
                };

                sendRequest("POST", `https://edusp-api.ip.tv/tms/task/${id}/answer`, draft_body, (response) => {
                    let response_json = JSON.parse(response.responseText);
                    let task_id = response_json.id;

                    console.log("[CMSP] Draft criado. ID Tarefa:", task_id);

                    // Passo 2: Pegar Respostas Reais
                    let get_answers_url = `https://edusp-api.ip.tv/tms/task/${id}/answer/${task_id}?with_task=true&with_genre=true&with_questions=true&with_assessed_skills=true`;

                    sendRequest("GET", get_answers_url, null, (response) => {
                        let get_responses = JSON.parse(response.responseText);

                        // Passo 3: Transformar e Enviar
                        let body_to_send = transformJson(get_responses);
                        console.log("[CMSP] Corpo do envio:", JSON.stringify(body_to_send));

                        sendRequest("PUT", `https://edusp-api.ip.tv/tms/task/${id}/answer/${task_id}`, body_to_send, (finalResponse) => {
                            if (finalResponse.status !== 200) {
                                console.error("[CMSP] Falha no envio final:", finalResponse.responseText);
                                alert("Erro ao enviar respostas: " + finalResponse.statusText);
                            } else {
                                console.log("[CMSP] Sucesso! Respostas enviadas.");
                            }
                        });
                    });
                });
            }
        }
    });

    observer.observe(document.body, { childList: true, subtree: true });

    let oldHref = document.location.href;
})();
